INSERT INTO "public"."_function_backups_20251118" ("function_name", "function_definition", "backed_up_at") VALUES
	('get_complete_schema', 'CREATE OR REPLACE FUNCTION public.get_complete_schema()
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    result jsonb;
BEGIN
    -- Get all enums
    WITH enum_types AS (
        SELECT 
            t.typname as enum_name,
            array_agg(e.enumlabel ORDER BY e.enumsortorder) as enum_values
        FROM pg_type t
        JOIN pg_enum e ON t.oid = e.enumtypid
        JOIN pg_catalog.pg_namespace n ON n.oid = t.typnamespace
        WHERE n.nspname = ''public''
        GROUP BY t.typname
    )
    SELECT jsonb_build_object(
        ''enums'',
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    ''name'', enum_name,
                    ''values'', to_jsonb(enum_values)
                )
            ),
            ''[]''::jsonb
        )
    )
    FROM enum_types
    INTO result;

    -- Get all tables with their details
    WITH RECURSIVE 
    columns_info AS (
        SELECT 
            c.oid as table_oid,
            c.relname as table_name,
            a.attname as column_name,
            format_type(a.atttypid, a.atttypmod) as column_type,
            a.attnotnull as notnull,
            pg_get_expr(d.adbin, d.adrelid) as column_default,
            CASE 
                WHEN a.attidentity != '''' THEN true
                WHEN pg_get_expr(d.adbin, d.adrelid) LIKE ''nextval%'' THEN true
                ELSE false
            END as is_identity,
            EXISTS (
                SELECT 1 FROM pg_constraint con 
                WHERE con.conrelid = c.oid 
                AND con.contype = ''p'' 
                AND a.attnum = ANY(con.conkey)
            ) as is_pk
        FROM pg_class c
        JOIN pg_namespace n ON n.oid = c.relnamespace
        LEFT JOIN pg_attribute a ON a.attrelid = c.oid
        LEFT JOIN pg_attrdef d ON d.adrelid = c.oid AND d.adnum = a.attnum
        WHERE n.nspname = ''public'' 
        AND c.relkind = ''r''
        AND a.attnum > 0 
        AND NOT a.attisdropped
    ),
    fk_info AS (
        SELECT 
            c.oid as table_oid,
            jsonb_agg(
                jsonb_build_object(
                    ''name'', con.conname,
                    ''column'', col.attname,
                    ''foreign_schema'', fs.nspname,
                    ''foreign_table'', ft.relname,
                    ''foreign_column'', fcol.attname,
                    ''on_delete'', CASE con.confdeltype
                        WHEN ''a'' THEN ''NO ACTION''
                        WHEN ''c'' THEN ''CASCADE''
                        WHEN ''r'' THEN ''RESTRICT''
                        WHEN ''n'' THEN ''SET NULL''
                        WHEN ''d'' THEN ''SET DEFAULT''
                        ELSE NULL
                    END
                )
            ) as foreign_keys
        FROM pg_class c
        JOIN pg_constraint con ON con.conrelid = c.oid
        JOIN pg_attribute col ON col.attrelid = con.conrelid AND col.attnum = ANY(con.conkey)
        JOIN pg_class ft ON ft.oid = con.confrelid
        JOIN pg_namespace fs ON fs.oid = ft.relnamespace
        JOIN pg_attribute fcol ON fcol.attrelid = con.confrelid AND fcol.attnum = ANY(con.confkey)
        WHERE con.contype = ''f''
        GROUP BY c.oid
    ),
    index_info AS (
        SELECT 
            c.oid as table_oid,
            jsonb_agg(
                jsonb_build_object(
                    ''name'', i.relname,
                    ''using'', am.amname,
                    ''columns'', (
                        SELECT jsonb_agg(a.attname ORDER BY array_position(ix.indkey, a.attnum))
                        FROM unnest(ix.indkey) WITH ORDINALITY as u(attnum, ord)
                        JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = u.attnum
                    )
                )
            ) as indexes
        FROM pg_class c
        JOIN pg_index ix ON ix.indrelid = c.oid
        JOIN pg_class i ON i.oid = ix.indexrelid
        JOIN pg_am am ON am.oid = i.relam
        WHERE NOT ix.indisprimary
        GROUP BY c.oid
    ),
    policy_info AS (
        SELECT 
            c.oid as table_oid,
            jsonb_agg(
                jsonb_build_object(
                    ''name'', pol.polname,
                    ''command'', CASE pol.polcmd
                        WHEN ''r'' THEN ''SELECT''
                        WHEN ''a'' THEN ''INSERT''
                        WHEN ''w'' THEN ''UPDATE''
                        WHEN ''d'' THEN ''DELETE''
                        WHEN ''*'' THEN ''ALL''
                    END,
                    ''roles'', (
                        SELECT string_agg(quote_ident(r.rolname), '', '')
                        FROM pg_roles r
                        WHERE r.oid = ANY(pol.polroles)
                    ),
                    ''using'', pg_get_expr(pol.polqual, pol.polrelid),
                    ''check'', pg_get_expr(pol.polwithcheck, pol.polrelid)
                )
            ) as policies
        FROM pg_class c
        JOIN pg_policy pol ON pol.polrelid = c.oid
        GROUP BY c.oid
    ),
    trigger_info AS (
        SELECT 
            c.oid as table_oid,
            jsonb_agg(
                jsonb_build_object(
                    ''name'', t.tgname,
                    ''timing'', CASE 
                        WHEN t.tgtype & 2 = 2 THEN ''BEFORE''
                        WHEN t.tgtype & 4 = 4 THEN ''AFTER''
                        WHEN t.tgtype & 64 = 64 THEN ''INSTEAD OF''
                    END,
                    ''events'', (
                        CASE WHEN t.tgtype & 1 = 1 THEN ''INSERT''
                             WHEN t.tgtype & 8 = 8 THEN ''DELETE''
                             WHEN t.tgtype & 16 = 16 THEN ''UPDATE''
                             WHEN t.tgtype & 32 = 32 THEN ''TRUNCATE''
                        END
                    ),
                    ''statement'', pg_get_triggerdef(t.oid)
                )
            ) as triggers
        FROM pg_class c
        JOIN pg_trigger t ON t.tgrelid = c.oid
        WHERE NOT t.tgisinternal
        GROUP BY c.oid
    ),
    table_info AS (
        SELECT DISTINCT 
            c.table_oid,
            c.table_name,
            jsonb_agg(
                jsonb_build_object(
                    ''name'', c.column_name,
                    ''type'', c.column_type,
                    ''notnull'', c.notnull,
                    ''default'', c.column_default,
                    ''identity'', c.is_identity,
                    ''is_pk'', c.is_pk
                ) ORDER BY c.column_name
            ) as columns,
            COALESCE(fk.foreign_keys, ''[]''::jsonb) as foreign_keys,
            COALESCE(i.indexes, ''[]''::jsonb) as indexes,
            COALESCE(p.policies, ''[]''::jsonb) as policies,
            COALESCE(t.triggers, ''[]''::jsonb) as triggers
        FROM columns_info c
        LEFT JOIN fk_info fk ON fk.table_oid = c.table_oid
        LEFT JOIN index_info i ON i.table_oid = c.table_oid
        LEFT JOIN policy_info p ON p.table_oid = c.table_oid
        LEFT JOIN trigger_info t ON t.table_oid = c.table_oid
        GROUP BY c.table_oid, c.table_name, fk.foreign_keys, i.indexes, p.policies, t.triggers
    )
    SELECT result || jsonb_build_object(
        ''tables'',
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    ''name'', table_name,
                    ''columns'', columns,
                    ''foreign_keys'', foreign_keys,
                    ''indexes'', indexes,
                    ''policies'', policies,
                    ''triggers'', triggers
                )
            ),
            ''[]''::jsonb
        )
    )
    FROM table_info
    INTO result;

    -- Get all functions
    WITH function_info AS (
        SELECT 
            p.proname AS name,
            pg_get_functiondef(p.oid) AS definition
        FROM pg_proc p
        JOIN pg_namespace n ON n.oid = p.pronamespace
        WHERE n.nspname = ''public''
        AND p.prokind = ''f''
    )
    SELECT result || jsonb_build_object(
        ''functions'',
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    ''name'', name,
                    ''definition'', definition
                )
            ),
            ''[]''::jsonb
        )
    )
    FROM function_info
    INTO result;

    RETURN result;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('handle_deal_changes', 'CREATE OR REPLACE FUNCTION public.handle_deal_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  IF NEW.property_id IS NOT NULL THEN
    -- Use the format_deal_name function for consistency
    NEW.deal_name := public.format_deal_name(NEW.property_id);
  END IF;
  RETURN NEW;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('check_deal_allocation_sum', 'CREATE OR REPLACE FUNCTION public.check_deal_allocation_sum()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
    total_allocated DECIMAL(15,2);
    transaction_total DECIMAL(15,2);
BEGIN
    -- For DELETE trigger, use OLD instead of NEW
    IF TG_OP = ''DELETE'' THEN
        -- Calculate sum of all deal allocations for this transaction
        SELECT COALESCE(SUM(allocation_amount), 0) INTO total_allocated
        FROM bsi_transactions_deals
        WHERE transaction_id = OLD.transaction_id;

        -- Get the transaction amount
        SELECT transaction_amount INTO transaction_total
        FROM bsi_transactions
        WHERE id = OLD.transaction_id;
    ELSE
        -- Calculate sum of all deal allocations for this transaction
        SELECT COALESCE(SUM(allocation_amount), 0) INTO total_allocated
        FROM bsi_transactions_deals
        WHERE transaction_id = NEW.transaction_id;

        -- Get the transaction amount
        SELECT transaction_amount INTO transaction_total
        FROM bsi_transactions
        WHERE id = NEW.transaction_id;
    END IF;

    -- Check if total allocated exceeds transaction amount
    IF total_allocated > ABS(transaction_total) THEN
        RAISE EXCEPTION ''Total deal allocations (%) cannot exceed transaction amount (%)'', 
            total_allocated, ABS(transaction_total);
    END IF;

    RETURN NEW;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('format_deal_name', 'CREATE OR REPLACE FUNCTION public.format_deal_name(property_id bigint)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    formatted_name text;
BEGIN
    SELECT 
        CONCAT_WS('', '', 
            p.address_street, 
            p.address_suite_apt, 
            p.address_city || '', '' || p.address_state || '' '' || p.address_postal_code
        )
    INTO formatted_name
    FROM public.property p
    WHERE p.id = property_id;

    RETURN formatted_name;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('update_property_address', 'CREATE OR REPLACE FUNCTION public.update_property_address()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE 
  new_address text;
BEGIN
  IF length(new.address_state_long::text) > 2 THEN
    new.address_state := get_state_code(new.address_state_long::text);
  END IF;

  -- Pass null for country parameter to exclude it from formatting
  new_address := format_address(new.address_street, new.address_suite_apt, new.address_city, new.address_state::text, new.address_postal_code, null, null);
  
  new.address = new_address;
  return new;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('format_address_7param', 'CREATE OR REPLACE FUNCTION public.format_address(po_box text, street text, apt_suite text, city text, state text, postal_code text, country text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
DECLARE
    formatted_address text;
BEGIN
    -- Initialize an array to hold address components (excluding country)
    formatted_address := TRIM(BOTH '', '' FROM
        array_to_string(
            ARRAY_REMOVE(
                ARRAY[
                    NULLIF(street, ''''),
                    NULLIF(apt_suite, ''''),
                    NULLIF(city, ''''),
                    CASE
                        WHEN COALESCE(state, '''') <> '''' AND COALESCE(postal_code, '''') <> '''' THEN
                            state || '' '' || postal_code
                        WHEN COALESCE(state, '''') <> '''' THEN
                            state
                        WHEN COALESCE(postal_code, '''') <> '''' THEN
                            postal_code
                        ELSE
                            NULL
                    END,
                    -- Removed country from array
                    CASE 
                        WHEN COALESCE(po_box, '''') <> '''' THEN
                            ''PO Box '' || po_box 
                        ELSE 
                            NULL 
                    END
                ],
                NULL
            ),
            '', ''
        )
    );

    -- Return the formatted address
    RETURN formatted_address;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('format_address_6param', 'CREATE OR REPLACE FUNCTION public.format_address(street text DEFAULT NULL::text, suite_apt text DEFAULT NULL::text, city text DEFAULT NULL::text, state text DEFAULT NULL::text, postal_code text DEFAULT NULL::text, country text DEFAULT ''United States''::text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''public'', ''pg_temp''
AS $function$
BEGIN
  RETURN TRIM(CONCAT_WS('', '',
    NULLIF(CONCAT_WS('' '', street, suite_apt), ''''),
    NULLIF(city, ''''),
    NULLIF(state, ''''),
    NULLIF(postal_code, ''''),
    NULLIF(country, '''')
  ));
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('sync_matched_api_brex_transfers_to_bsi_transactions', 'CREATE OR REPLACE FUNCTION public.sync_matched_api_brex_transfers_to_bsi_transactions()
 RETURNS TABLE(inserted_count bigint, updated_count bigint, error_count bigint, errors jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_inserted_count bigint := 0;
    v_updated_count bigint := 0;
    v_error_count bigint := 0;
    v_errors jsonb := ''[]''::jsonb;
    v_transfer_record RECORD;
    v_transaction_id bigint;
    v_transaction_method text;
    v_transaction_status text;
    v_fed_reference_number text;
    v_amount_dollars numeric;
    v_duplicate_vendors jsonb;
BEGIN
    -- Validate vendor matching
    SELECT jsonb_agg(jsonb_build_object(''brex_vendor_id'', brex_vendor_id, ''issue'', issue_type))
    INTO v_duplicate_vendors
    FROM (
        SELECT 
            av.brex_vendor_id,
            CASE 
                WHEN COALESCE(user_count, 0) > 1 THEN ''Multiple user matches''
                WHEN COALESCE(org_count, 0) > 1 THEN ''Multiple org matches''
                WHEN COALESCE(user_count, 0) > 0 AND COALESCE(org_count, 0) > 0 THEN ''Has both user AND org matches''
            END as issue_type,
            COALESCE(user_count, 0) as user_count,
            COALESCE(org_count, 0) as org_count
        FROM api_brex_vendors av
        LEFT JOIN (
            SELECT brex_vendor_id, COUNT(*) as user_count
            FROM api_brex_vendors_clerk_users
            GROUP BY brex_vendor_id
        ) u ON u.brex_vendor_id = av.id
        LEFT JOIN (
            SELECT brex_vendor_id, COUNT(*) as org_count
            FROM api_brex_vendors_clerk_orgs
            GROUP BY brex_vendor_id
        ) o ON o.brex_vendor_id = av.id
        WHERE (COALESCE(user_count, 0) > 1) 
           OR (COALESCE(org_count, 0) > 1) 
           OR (COALESCE(user_count, 0) > 0 AND COALESCE(org_count, 0) > 0)
    ) violations;
    
    IF v_duplicate_vendors IS NOT NULL THEN
        RAISE EXCEPTION ''Vendor matching validation failed: %'', v_duplicate_vendors::text;
    END IF;

    FOR v_transfer_record IN
        SELECT DISTINCT
            at.brex_transfer_id,
            at.amount,
            at.amount_cents,
            at.process_date,
            at.status,
            at.external_memo,
            at.payment_type,
            at.fed_reference_number,
            at.raw_payload,
            -- Match by counterparty_id OR account number
            COALESCE(
                at.counterparty_id,
                (SELECT av.brex_vendor_id 
                 FROM api_brex_vendors av
                 WHERE av.account_number = at.counterparty_account_number
                   AND av.routing_number = at.counterparty_routing_number
                 LIMIT 1)
            ) as matched_vendor_id,
            (SELECT avcu.clerk_user_id 
             FROM api_brex_vendors_clerk_users avcu
             JOIN api_brex_vendors av ON av.id = avcu.brex_vendor_id
             WHERE av.brex_vendor_id = COALESCE(
                 at.counterparty_id,
                 (SELECT av2.brex_vendor_id 
                  FROM api_brex_vendors av2
                  WHERE av2.account_number = at.counterparty_account_number
                    AND av2.routing_number = at.counterparty_routing_number
                  LIMIT 1)
             )
            ) as clerk_user_id,
            (SELECT avco.clerk_org_id 
             FROM api_brex_vendors_clerk_orgs avco
             JOIN api_brex_vendors av ON av.id = avco.brex_vendor_id
             WHERE av.brex_vendor_id = COALESCE(
                 at.counterparty_id,
                 (SELECT av2.brex_vendor_id 
                  FROM api_brex_vendors av2
                  WHERE av2.account_number = at.counterparty_account_number
                    AND av2.routing_number = at.counterparty_routing_number
                  LIMIT 1)
             )
            ) as clerk_org_id
        FROM api_brex_transfers at
        WHERE (
            -- Has counterparty_id OR matchable by account
            at.counterparty_id IS NOT NULL
            OR EXISTS (
                SELECT 1 FROM api_brex_vendors av
                WHERE av.account_number = at.counterparty_account_number
                  AND av.routing_number = at.counterparty_routing_number
            )
        )
        -- Has user or org match
        AND (
            EXISTS (
                SELECT 1 FROM api_brex_vendors av
                JOIN api_brex_vendors_clerk_users avcu ON avcu.brex_vendor_id = av.id
                WHERE av.brex_vendor_id = COALESCE(
                    at.counterparty_id,
                    (SELECT av2.brex_vendor_id 
                     FROM api_brex_vendors av2
                     WHERE av2.account_number = at.counterparty_account_number
                       AND av2.routing_number = at.counterparty_routing_number
                     LIMIT 1)
                )
            )
            OR EXISTS (
                SELECT 1 FROM api_brex_vendors av
                JOIN api_brex_vendors_clerk_orgs avco ON avco.brex_vendor_id = av.id
                WHERE av.brex_vendor_id = COALESCE(
                    at.counterparty_id,
                    (SELECT av2.brex_vendor_id 
                     FROM api_brex_vendors av2
                     WHERE av2.account_number = at.counterparty_account_number
                       AND av2.routing_number = at.counterparty_routing_number
                     LIMIT 1)
                )
            )
        )
        -- Not already synced
        AND NOT EXISTS (
            SELECT 1 FROM bsi_transactions_api_brex_transfers btbt
            WHERE btbt.brex_transfer_id = at.brex_transfer_id
        )
    LOOP
        v_fed_reference_number := COALESCE(
            v_transfer_record.fed_reference_number,
            (v_transfer_record.raw_payload->''counterparty''->>''fed_reference_number'')::text
        );

        -- Convert amount
        IF v_transfer_record.amount_cents IS NOT NULL THEN
            v_amount_dollars := v_transfer_record.amount_cents / 100.0;
            IF v_transfer_record.amount IS NOT NULL THEN
                IF ABS(v_amount_dollars - v_transfer_record.amount) > 0.01 THEN
                    RAISE EXCEPTION ''Amount inconsistency for transfer %'', v_transfer_record.brex_transfer_id;
                END IF;
            END IF;
        ELSIF v_transfer_record.amount IS NOT NULL THEN
            v_amount_dollars := v_transfer_record.amount;
        ELSE
            v_amount_dollars := NULL;
        END IF;

        -- Map payment_type
        CASE v_transfer_record.payment_type
            WHEN ''ACH'' THEN v_transaction_method := ''ach'';
            WHEN ''DOMESTIC_WIRE'' THEN v_transaction_method := ''wire'';
            WHEN ''INTERNATIONAL_WIRE'' THEN v_transaction_method := ''wire'';
            WHEN ''CHEQUE'' THEN v_transaction_method := ''check'';
            ELSE v_transaction_method := ''other'';
        END CASE;

        -- Map status
        CASE UPPER(TRIM(v_transfer_record.status))
            WHEN ''PROCESSING'' THEN v_transaction_status := ''processing'';
            WHEN ''COMPLETED'' THEN v_transaction_status := ''completed'';
            WHEN ''FAILED'' THEN v_transaction_status := ''failed'';
            WHEN ''CANCELLED'', ''CANCELED'' THEN v_transaction_status := ''canceled'';
            WHEN ''PENDING'' THEN v_transaction_status := ''pending'';
            WHEN ''SCHEDULED'' THEN v_transaction_status := ''scheduled'';
            WHEN ''INITIATED'' THEN v_transaction_status := ''initiated'';
            WHEN ''PROCESSED'' THEN v_transaction_status := ''processed'';
            ELSE v_transaction_status := COALESCE(
                    LOWER((v_transfer_record.raw_payload->>''status'')::text),
                    ''pending''
                );
        END CASE;

        IF v_transaction_status NOT IN (''canceled'',''completed'',''failed'',''initiated'',''on_hold'',''owed'',''pending'',''pending_approval'',''processed'',''processing'',''refunded'',''returned'',''scheduled'') THEN
            v_transaction_status := ''pending'';
        END IF;

        INSERT INTO bsi_transactions (
            transaction_amount,
            transaction_date,
            transaction_method,
            transaction_status,
            reference_number,
            external_memo,
            ledger_entry_type,
            created_at,
            updated_at
        )
        VALUES (
            v_amount_dollars,
            COALESCE(v_transfer_record.process_date::timestamp with time zone, NOW()),
            v_transaction_method::transaction_method,
            v_transaction_status::transaction_status,
            v_fed_reference_number,
            v_transfer_record.external_memo,
            NULL,
            NOW(),
            NOW()
        )
        RETURNING id INTO v_transaction_id;

        IF v_transfer_record.clerk_user_id IS NOT NULL OR v_transfer_record.clerk_org_id IS NOT NULL THEN
            INSERT INTO bsi_transactions_investors (
                transaction_id,
                clerk_user_id,
                clerk_org_id,
                allocation_amount,
                created_at
            )
            VALUES (
                v_transaction_id,
                v_transfer_record.clerk_user_id,
                v_transfer_record.clerk_org_id,
                NULL,
                NOW()
            );
        END IF;

        INSERT INTO bsi_transactions_api_brex_transfers (
            transaction_id,
            brex_transfer_id,
            created_at
        )
        VALUES (
            v_transaction_id,
            v_transfer_record.brex_transfer_id,
            NOW()
        );

        v_inserted_count := v_inserted_count + 1;
    END LOOP;

    RETURN QUERY SELECT v_inserted_count, v_updated_count, v_error_count, v_errors;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('count_pending_brex_transfer_syncs', 'CREATE OR REPLACE FUNCTION public.count_pending_brex_transfer_syncs()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_count bigint;
BEGIN
    SELECT COUNT(*) INTO v_count
    FROM api_brex_transfers at
    WHERE at.counterparty_id IS NOT NULL
    AND (
        EXISTS (
            SELECT 1 FROM api_brex_vendors av
            JOIN api_brex_vendors_clerk_users avcu ON avcu.brex_vendor_id = av.id
            WHERE av.brex_vendor_id = at.counterparty_id
        )
        OR EXISTS (
            SELECT 1 FROM api_brex_vendors av
            JOIN api_brex_vendors_clerk_orgs avco ON avco.brex_vendor_id = av.id
            WHERE av.brex_vendor_id = at.counterparty_id
        )
    )
    AND NOT EXISTS (
        SELECT 1 FROM bsi_transactions_api_brex_transfers btbt
        WHERE btbt.brex_transfer_id = at.brex_transfer_id
    );
    
    RETURN v_count;
END;
$function$
', '2025-11-18 14:01:16.037246+00'),
	('is_admin', 'CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM auth_clerk_users acu
    WHERE acu.clerk_user_id = (auth.jwt() ->> ''sub''::text)
    AND acu.role = ''admin''::user_role_internal
  );
$function$
', '2025-11-18 14:01:16.037246+00');


